const TZ = 'Africa/Lagos';
const s = (v) => String(v === null || v === undefined ? '' : v).trim();
const todayStr = () => new Intl.DateTimeFormat('en-CA', { timeZone: TZ }).format(new Date());
const nowIso = () => new Date(Date.now() + 3600000).toISOString().replace(/\.\d{3}Z$/, '+01:00');
const uid = (p) => p + '-' + Date.now().toString(36).toUpperCase() + '-' + Math.random().toString(36).slice(2, 7).toUpperCase();
const isEmail = (e) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s(e));
const isDate = (d) => /^\d{4}-\d{2}-\d{2}$/.test(d) && !isNaN(Date.parse(d + 'T00:00:00Z'));
const daysBetween = (a, b) => Math.floor((Date.parse(b + 'T00:00:00Z') - Date.parse(a + 'T00:00:00Z')) / 86400000);
const mkLog = (o) => Object.assign({ event_id: uid('EVT'), customer_id: '', email: '', event_type: '', campaign_id: '', email_sequence: '', message_id: '', booking_id: '', timestamp: nowIso(), status: '', error: '', metadata: '' }, o);
const mkErr = (o) => Object.assign({ error_id: uid('ERR'), workflow: '', customer_id: '', node: '', error_type: 'UNKNOWN', message: '', timestamp: nowIso(), retry_count: 0, resolved: 'FALSE', execution_id: String($execution.id) }, o);

const item = $input.first();
const hdr = item.json.headers || {};
const body = item.json.body || {};
let sigOk = false, sigReason = '';
try {
  const secret = $env.CAL_WEBHOOK_SECRET;
  if (!secret) {
    sigReason = 'NO_SECRET_CONFIGURED';
  } else {
    const crypto = require('crypto');
    const raw = await this.helpers.getBinaryDataBuffer(0, 'data');
    const expected = crypto.createHmac('sha256', secret).update(raw).digest('hex');
    const got = s(hdr['x-cal-signature-256']).replace(/^sha256=/i, '');
    const a = Buffer.from(expected), b = Buffer.from(got);
    sigOk = a.length === b.length && crypto.timingSafeEqual(a, b);
    if (!sigOk) sigReason = 'SIGNATURE_MISMATCH';
  }
} catch (e) {
  sigReason = 'SIGNATURE_CHECK_ERROR: ' + (e && e.message ? e.message : e);
}
const trig = s(body.triggerEvent);
const p = body.payload || {};
const att = Array.isArray(p.attendees) && p.attendees[0] ? p.attendees[0] : {};
const resp = p.responses || {};
const rv = (k) => { const v = resp[k]; return v && typeof v === 'object' && 'value' in v ? v.value : (v === undefined ? '' : v); };
const email = s(att.email || rv('email')).toLowerCase();
const known = ['BOOKING_CREATED', 'BOOKING_CANCELLED', 'BOOKING_RESCHEDULED'].includes(trig);
const valid = known && !!s(p.uid) && !!s(p.startTime) && !!email;
const reason = !known ? 'UNKNOWN_EVENT' : (valid ? '' : 'MISSING_FIELDS');
return [{ json: { sigOk, sigReason, valid, reason, trig, uid: s(p.uid), rescheduleUid: s(p.rescheduleUid || body.rescheduleUid),
  startTime: s(p.startTime), endTime: s(p.endTime), email, attendeeName: s(att.name || rv('name')),
  customerIdAnswer: s(rv('customer_id')), event_id: 'CAL-' + s(p.uid) + '-' + trig } }];

