const TZ = 'Africa/Lagos';
const s = (v) => String(v === null || v === undefined ? '' : v).trim();
const todayStr = () => new Intl.DateTimeFormat('en-CA', { timeZone: TZ }).format(new Date());
const nowIso = () => new Date(Date.now() + 3600000).toISOString().replace(/\.\d{3}Z$/, '+01:00');
const uid = (p) => p + '-' + Date.now().toString(36).toUpperCase() + '-' + Math.random().toString(36).slice(2, 7).toUpperCase();
const isEmail = (e) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s(e));
const isDate = (d) => /^\d{4}-\d{2}-\d{2}$/.test(d) && !isNaN(Date.parse(d + 'T00:00:00Z'));
const daysBetween = (a, b) => Math.floor((Date.parse(b + 'T00:00:00Z') - Date.parse(a + 'T00:00:00Z')) / 86400000);
const mkLog = (o) => Object.assign({ event_id: uid('EVT'), customer_id: '', email: '', event_type: '', campaign_id: '', email_sequence: '', message_id: '', booking_id: '', timestamp: nowIso(), status: '', error: '', metadata: '' }, o);
const mkErr = (o) => Object.assign({ error_id: uid('ERR'), workflow: '', customer_id: '', node: '', error_type: 'UNKNOWN', message: '', timestamp: nowIso(), retry_count: 0, resolved: 'FALSE', execution_id: String($execution.id) }, o);

const V = $('Verify & Parse').first().json;
const S = $('Get Settings').first().json.settings;
const log = $input.all().map(i => i.json).filter(l => l.event_id);
const customers = $('Read Customers').all().map(i => i.json);
const now = nowIso();
if (log.some(l => s(l.event_id) === V.event_id)) return [{ json: { kind: 'DUPLICATE' } }];

let cust = null, note = '';
if (V.trig === 'BOOKING_RESCHEDULED' && V.rescheduleUid) {
  const m = customers.filter(c => s(c.booking_id) === V.rescheduleUid);
  if (m.length === 1) cust = m[0];
}
if (!cust && V.trig === 'BOOKING_CANCELLED') {
  const m = customers.filter(c => s(c.booking_id) === V.uid);
  if (m.length === 1) cust = m[0];
}
if (!cust && V.customerIdAnswer) {
  const m = customers.filter(c => s(c.customer_id) === V.customerIdAnswer);
  if (m.length === 1) {
    cust = m[0];
    if (s(cust.email).toLowerCase() !== V.email) note = 'EMAIL_MISMATCH: sheet ' + s(cust.email) + ' vs booking ' + V.email;
  }
}
if (!cust && V.email) {
  const m = customers.filter(c => s(c.email).toLowerCase() === V.email);
  if (m.length === 1) cust = m[0];
  else if (m.length > 1) note = 'AMBIGUOUS_EMAIL';
}
const row = (type, cid, status, err, meta) => mkLog({ event_id: V.event_id, customer_id: cid, email: V.email, event_type: type,
  campaign_id: s(S.campaign_id), booking_id: V.uid, timestamp: now, status, error: err || '', metadata: meta || '' });

if (!cust) {
  return [{ json: { kind: 'UNMATCHED',
    logRow: row('BOOKING_UNMATCHED', '', 'UNMATCHED', note || 'NO_CUSTOMER_MATCH', V.trig),
    errorRow: mkErr({ workflow: 'WF3 - Cal.com Booking Webhook', node: 'Process Booking', error_type: 'UNMATCHED_BOOKING',
      message: 'No customer matched for booking ' + V.uid + ' (' + V.email + ') ' + note }),
    alert: { to: s(S.operator_email), subject: 'Unmatched booking needs attention',
      text: 'A ' + V.trig + ' event could not be matched to a customer.\n\nBooking ID: ' + V.uid + '\nAttendee: ' + V.attendeeName + ' <' + V.email + '>\nStart: ' + V.startTime + '\nNote: ' + (note || 'none') + '\n\nCheck the Customers and Campaign_Log sheets.' } } }];
}
const cid = s(cust.customer_id);
const existing = s(cust.booking_id);
let logType, update = null, meta = note;
if (V.trig === 'BOOKING_CREATED') {
  logType = 'BOOKING_CREATED';
  if (s(cust.booking_status) === 'BOOKED' && existing && existing !== V.uid) {
    meta = ('EXTRA_BOOKING ' + note).trim();
  } else {
    update = { customer_id: cid, booking_status: 'BOOKED', campaign_status: 'STOPPED', stop_reason: 'BOOKED', booking_id: V.uid, booking_date: V.startTime, updated_at: now };
  }
} else if (V.trig === 'BOOKING_CANCELLED') {
  logType = 'BOOKING_CANCELLED';
  if (existing && existing !== V.uid) {
    meta = ('NOT_CURRENT_BOOKING ' + note).trim();
  } else {
    update = { customer_id: cid, booking_status: 'CANCELLED', updated_at: now };
  }
} else {
  logType = 'BOOKING_RESCHEDULED';
  update = { customer_id: cid, booking_status: 'BOOKED', booking_id: V.uid, booking_date: V.startTime, updated_at: now };
  if (s(cust.booking_status) !== 'BOOKED') { update.campaign_status = 'STOPPED'; update.stop_reason = 'BOOKED'; }
}
return [{ json: { kind: update ? 'MATCHED' : 'LOGONLY', logRow: row(logType, cid, 'SUCCESS', '', meta), customerUpdate: update } }];
